import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        zeros_odd = 0
        ones_odd = 0
        zeros_even = 0
        ones_even = 0

        for idx, char in enumerate(S):
            pos = idx + 1
            if pos % 2 == 1:
                if char == '0':
                    zeros_odd += 1
                else:
                    ones_odd += 1
            else:
                if char == '0':
                    zeros_even += 1
                else:
                    ones_even += 1

        count_01 = 0
        prev = None
        for char in S:
            if prev == '0' and char == '1':
                count_01 += 1
            prev = char

        max_01 = count_01

        if zeros_odd > 0 and ones_even > 0:
            max_01 += 1

        if zeros_even > 0 and ones_odd > 0:
            max_01 += 1

        results.append(str(max_01))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
